package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

// fixtureRootEnv points the named report golden tests at another tree that
// holds testdata/fixtures/report, instead of this repository. The recorder
// (scripts/record-report-fixtures.sh) sets it to the fresh tree it assembled,
// so a re-record regenerates the fresh pack and never writes the live one. The
// receipts name the input as testdata/fixtures/report/<case>/input relative to
// the run's working directory, so the fresh tree keeps that layout under its
// root and the regenerated bytes are the bytes the live pack will carry.
//
// It applies to TestReportProjections, TestReportSARIFParity,
// TestReportSpaceliftParity, TestReportRecordedExitCodes,
// TestReportEnvironmentDiagnostic and TestReportEvidencePack only.
const fixtureRootEnv = "CTFKIT_FIXTURE_ROOT"

// switchesInCI refuses CTFKIT_RERECORD or CTFKIT_FIXTURE_ROOT in a CI job. A
// golden test that rewrites the pack it compares against, or reads another
// tree, passes without testing anything, so in CI either switch is a failure,
// not a mode. The recorder runs its tests under env -i, which drops CI.
func switchesInCI(getenv func(string) string) error {
	if getenv("CI") == "" {
		return nil
	}
	for _, name := range []string{rerecordEnv, fixtureRootEnv} {
		if getenv(name) != "" {
			return fmt.Errorf("%s is set in CI: the golden tests would compare against what they wrote or read another tree", name)
		}
	}
	return nil
}

// refuseSwitchesInCI fails the test when switchesInCI does.
func refuseSwitchesInCI(t *testing.T) {
	t.Helper()
	if err := switchesInCI(os.Getenv); err != nil {
		t.Fatal(err)
	}
}

// goldenRoot is the working directory of the named report golden tests.
func goldenRoot(t *testing.T) string {
	t.Helper()
	refuseSwitchesInCI(t)

	root := os.Getenv(fixtureRootEnv)
	if root == "" {
		return repoRoot
	}
	if !filepath.IsAbs(root) {
		t.Fatalf("%s must be an absolute path, got %q", fixtureRootEnv, root)
	}
	return root
}

// rerecording reports whether CTFKIT_RERECORD=1 asks the golden tests to
// write what they render over the expected files. In that mode a test renders
// every case whose directory exists, whether or not its expected file does,
// so a fresh tree with an empty expected/ is filled completely.
func rerecording() bool { return os.Getenv(rerecordEnv) == "1" }

// writeExpected writes one regenerated expected artifact of a report case,
// relative to the working directory the golden tests chdir to.
func writeExpected(t *testing.T, name, file string, body []byte) {
	t.Helper()

	dir := filepath.Join("testdata/fixtures/report", name, "expected")
	if err := os.MkdirAll(dir, 0o755); err != nil { //nolint:gosec // a committed fixture tree
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, file), body, 0o644); err != nil { //nolint:gosec // a committed fixture, read by everyone
		t.Fatal(err)
	}
}

func TestRerecordSwitchesAreRefusedInCI(t *testing.T) {
	tests := []struct {
		name    string
		env     map[string]string
		refused bool
	}{
		{"CI with CTFKIT_RERECORD", map[string]string{"CI": "true", rerecordEnv: "1"}, true},
		{"CI with CTFKIT_FIXTURE_ROOT", map[string]string{"CI": "true", fixtureRootEnv: "/tmp/fresh"}, true},
		{"CI alone", map[string]string{"CI": "true"}, false},
		{"CTFKIT_RERECORD outside CI", map[string]string{rerecordEnv: "1"}, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := switchesInCI(func(k string) string { return tt.env[k] })
			if (err != nil) != tt.refused {
				t.Errorf("switchesInCI = %v, refused want %v", err, tt.refused)
			}
		})
	}
}

// TestReportSpaceliftParity renders the Spacelift metadata file of every
// recorded case and compares it with expected/ctfkit.custom.spacelift.json,
// byte for byte. The file lands in the working directory, so each case runs in
// a scratch one with absolute paths.
func TestReportSpaceliftParity(t *testing.T) {
	root, err := filepath.Abs(goldenRoot(t))
	if err != nil {
		t.Fatal(err)
	}
	t.Chdir(root)
	names := recordedCases(t)

	for _, name := range names {
		want := filepath.Join(root, "testdata/fixtures/report", name, "expected", "ctfkit.custom.spacelift.json")
		if !rerecording() && !exists(want) {
			continue // schema-4-stub stops before it renders anything
		}

		t.Run(name, func(t *testing.T) {
			input := filepath.Join(root, fixturePath(name))
			args := append([]string{
				"--path", input,
				"--format", "markdown,spacelift",
				"--out-dir", t.TempDir(),
			}, fixtureContext...)
			if testsJSON := filepath.Join(input, "tests.json"); exists(testsJSON) {
				args = append(args, "--tests-json", testsJSON)
			}

			work := t.TempDir()
			t.Chdir(work)
			if _, code := runReport(t, args...); code == ExitEnvironment {
				if rerecording() {
					return // an exit-2 case renders no projection
				}
				t.Fatalf("report --format spacelift exited 2")
			}
			got := readFile(t, filepath.Join(work, "ctfkit.custom.spacelift.json"))

			if rerecording() {
				t.Chdir(root)
				writeExpected(t, name, "ctfkit.custom.spacelift.json", got)
			}
			assertSameBytes(t, name+"/expected/ctfkit.custom.spacelift.json", readFile(t, want), got)
		})
	}
}
